<?php
declare(strict_types=1);
// Optional organization records share the workspace's membership and revision controls.
function op_list(mixed $rows,int $limit): array {if(!is_array($rows)||!array_is_list($rows)||count($rows)>$limit)fail(422,'Liste d’organisation invalide.');return $rows;}
function op_enum(mixed $value,array $allowed): void {if(!in_array($value,$allowed,true))fail(422,'État d’organisation inconnu.');}
function op_date(mixed $value,bool $required=false): void {if(!valid_date($value,$required))fail(422,'Date d’organisation invalide.');}
function op_rows(mixed $rows,int $limit): array {$rows=op_list($rows,$limit);$seen=[];foreach($rows as $r){if(!is_array($r))fail(422,'Fiche d’organisation invalide.');$id=clean_text($r['id']??null,100,'identifiant',true);if(isset($seen[$id]))fail(422,'Identifiant d’organisation en double.');$seen[$id]=true;}return $rows;}
function op_money(mixed $amount,bool $nullable=false): void {if($nullable&&$amount===null)return;if(!is_int($amount)||$amount<0||$amount>10000000000)fail(422,'Montant en centimes invalide.');}
function op_time(string $date,mixed $time,DateTimeZone $zone): void {
    if(!is_string($time)||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/D',$time))fail(422,'Heure invalide.');
    $wall=$date.' '.$time;$instant=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$wall,$zone);
    if(!$instant||$instant->format('Y-m-d H:i')!==$wall)fail(422,'Heure inexistante au changement d’heure.');
    foreach([-3600,3600] as $offset)if($instant->setTimestamp($instant->getTimestamp()+$offset)->format('Y-m-d H:i')===$wall)fail(422,'Heure ambiguë au changement d’heure.');
}
function validate_operations(array $data,array $shows,array $ids): void {
    $projects=op_rows($data['productions']??[],200);$resources=op_rows($data['resources']??[],500);$slots=op_rows($data['planningSlots']??[],5000);$projectMap=[];$resourceMap=[];$requests=array_column($data['requests'],null,'id');
    foreach($resources as $r){$resourceMap[$r['id']]=$r;clean_text($r['name']??null,250,'ressource',true);op_enum($r['kind']??null,['equipment','space','vehicle']);$q=$r['quantity']??null;$u=$r['unavailable']??null;if(!is_int($q)||$q<1||$q>10000||!is_int($u)||$u<0||$u>$q||($r['kind']!=='equipment'&&$q!==1))fail(422,'Stock invalide.');foreach(['location'=>250,'note'=>4000] as $key=>$max)clean_text($r[$key]??'',$max,$key);}
    foreach($projects as $p){
        clean_text($p['title']??null,250,'production',true);$show=clean_text($p['show']??'',250,'spectacle');if($show!==''&&!isset($shows[$show]))fail(422,'Spectacle de production absent.');op_enum($p['stage']??null,['preparation','tour','closed']);op_enum($p['basis']??null,['unspecified','net','gross']);
        $zoneName=clean_text($p['timeZone']??'Europe/Paris',100,'fuseau',true);try{$zone=new DateTimeZone($zoneName);}catch(Throwable){fail(422,'Fuseau inconnu.');}$projectMap[$p['id']]=['zone'=>$zone];
        clean_text($p['owner']??'',250,'responsable');clean_text($p['note']??'',8000,'notes');op_date($p['created']??'');
        $links=op_list($p['requestIds']??[],5000);if(count(array_unique($links))!==count($links))fail(422,'Demande liée en double.');foreach($links as $id){if(!is_string($id)||!isset($requests[$id]))fail(422,'Demande de production absente.');$r=$requests[$id];if($show!==''&&$r['show']!==$show&&!in_array($show,$r['proposedShows']??[],true))fail(422,'Demande sans rapport avec ce spectacle.');}
        foreach(op_rows($p['budget']??[],1000) as $r){clean_text($r['label']??null,250,'ligne budgétaire',true);clean_text($r['category']??null,120,'catégorie',true);op_enum($r['flow']??null,['income','expense']);op_enum($r['stage']??null,['forecast','agreed','settled']);op_money($r['plannedCents']??null);op_money($r['actualCents']??null,true);op_date($r['due']??'');op_date($r['paidDate']??'');if($r['stage']==='settled'&&(($r['actualCents']??null)===null||empty($r['paidDate'])))fail(422,'Règlement incomplet.');$contact=$r['contactId']??'';if($contact!==''&&(!is_string($contact)||!isset($ids['contacts'][$contact])))fail(422,'Partenaire budgétaire absent.');clean_text($r['reference']??'',250,'référence');}
        foreach(op_rows($p['tasks']??[],500) as $r){clean_text($r['label']??null,250,'action',true);clean_text($r['owner']??'',250,'responsable');op_date($r['due']??'');if(!is_bool($r['done']??null))fail(422,'État d’action invalide.');}
        foreach(op_rows($p['documents']??[],500) as $r){clean_text($r['label']??null,250,'document',true);op_enum($r['kind']??null,['quote','contract','invoice','technical','authorization','other']);op_enum($r['stage']??null,['draft','expected','ready','signed','received']);op_date($r['due']??'');clean_text($r['reference']??'',250,'référence');clean_text($r['note']??'',4000,'note');$url=clean_text($r['url']??'',4000,'lien');if($url!==''){$parts=parse_url($url);if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(strtolower($parts['scheme']??''),['http','https'],true)||isset($parts['user'])||isset($parts['pass']))fail(422,'Lien de document invalide.');}}
    }
    foreach($data['schedule'] as $event){if(!empty($event['productionId'])&&!isset($projectMap[$event['productionId']]))fail(422,'Production du rendez-vous absente.');clean_text($event['assignee']??'',250,'responsable du rendez-vous');}
    foreach($slots as $s){$project=$projectMap[$s['productionId']??'']??null;if(!$project)fail(422,'Production du créneau absente.');clean_text($s['label']??null,250,'activité',true);op_enum($s['kind']??null,['rehearsal','setup','performance','travel','lodging','meeting','workshop','other']);op_enum($s['stage']??null,['draft','planned','done','cancelled']);op_date($s['date']??'',true);op_time($s['date'],$s['start']??null,$project['zone']);op_time($s['date'],$s['end']??null,$project['zone']);if($s['end']<=$s['start'])fail(422,'Fin du créneau invalide.');clean_text($s['place']??'',250,'lieu');clean_text($s['note']??'',8000,'consignes');$members=op_list($s['members']??[],100);foreach($members as $m)clean_text($m,250,'membre',true);if(count(array_unique($members))!==count($members))fail(422,'Membre affecté en double.');$seen=[];foreach(op_list($s['resources']??[],500) as $r){$id=$r['resourceId']??'';$q=$r['quantity']??null;if(!isset($resourceMap[$id])||isset($seen[$id])||!is_int($q)||$q<1||$q>10000)fail(422,'Ressource du créneau invalide.');$seen[$id]=true;}$actual=$s['actualMinutes']??null;if($actual!==null&&(!is_int($actual)||$actual<0||$actual>1440))fail(422,'Durée réalisée invalide.');}
}
